/**
 * @method
 * @name krakenfutures#fetchMarkets
 * @description Fetches the available trading markets from the exchange, Multi-collateral markets are returned as linear markets, but can be settled in multiple currencies
 * @see https://docs.kraken.com/api/docs/futures-api/trading/get-instruments
 * @param {object} [params] exchange specific params
 * @returns An array of market structures
 */
func (this *Krakenfutures) FetchMarketsAsync(optionalArgs ...any) <-chan AsyncResult[[]MarketInterface] {
	ch := make(chan AsyncResult[[]MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Krakenfutures) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetInstruments(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//    {
	//        "result": "success",
	//        "instruments": [
	//            {
	//                "symbol": "fi_ethusd_180928",
	//                "type": "futures_inverse", // futures_vanilla  // spot index
	//                "underlying": "rr_ethusd",
	//                "lastTradingTime": "2018-09-28T15:00:00.000Z",
	//                "tickSize": 0.1,
	//                "contractSize": 1,
	//                "tradeable": true,
	//                "marginLevels": [
	//                    {
	//                        "contracts":0,
	//                        "initialMargin":0.02,
	//                        "maintenanceMargin":0.01
	//                    },
	//                    {
	//                        "contracts":250000,
	//                        "initialMargin":0.04,
	//                        "maintenanceMargin":0.02
	//                    },
	//                    ...
	//                ],
	//                "isin": "GB00JVMLMP88",
	//                "retailMarginLevels": [
	//                    {
	//                        "contracts": 0,
	//                        "initialMargin": 0.5,
	//                        "maintenanceMargin": 0.25
	//                    }
	//                ],
	//                "tags": [],
	//            },
	//            {
	//                "symbol": "in_xbtusd",
	//                "type": "spot index",
	//                "tradeable":false
	//            }
	//        ]
	//        "serverTime": "2018-07-19T11:32:39.433Z"
	//    }
	//
	var instruments []any = SafeListTyped(response, "instruments")
	var result []any = []any{}
	for i := 0; i < len(instruments); i++ {
		var market any = instruments[i]
		var id *string = this.SafeString(market, "symbol")
		var marketType *string = this.SafeString(market, "type")
		var typeVar string
		var index bool = (strings.Index(*marketType, " index") >= 0)
		var linear any = nil
		var inverse any = nil
		var expiry any = nil
		if !index {
			linear = (strings.Index(*marketType, "_vanilla") >= 0)
			inverse = !(linear == true)
			var settleTime *string = this.SafeString(market, "lastTradingTime")
			typeVar = func() string {
				if settleTime == nil {
					return "swap"
				}
				return "future"
			}()
			if derefPtr := this.Parse8601(settleTime); derefPtr != nil {
				expiry = *derefPtr
			} else {
				expiry = nil
			}
		} else {
			typeVar = "index"
		}
		var swap bool = (typeVar == "swap")
		var future bool = (typeVar == "future")
		var symbol *string = id
		var split []string = strings.Split(*id, "_")
		var splitMarket *string = this.SafeString(split, 1, "")
		var baseId string = Slice(splitMarket, 0, len(*splitMarket)-3)
		var quoteId string = "usd" // always USD
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		// swap == perpetual
		var settle *string = nil
		var settleId *string = nil
		var cvtp *string = this.SafeString(market, "contractValueTradePrecision")
		var amountPrecision *float64 = this.ParseNumber(this.IntegerPrecisionToAmount(cvtp))
		var pricePrecision *float64 = this.SafeNumber(market, "tickSize")
		var contract bool = (swap || future || index)
		var swapOrFutures bool = (swap || future)
		if swapOrFutures {
			var exchangeType *string = this.SafeString(market, "type")
			if exchangeType != nil && *exchangeType == "futures_inverse" {
				settle = base
				settleId = SafeStringPtr(baseId)
				inverse = true
			} else {
				settle = quote
				settleId = SafeStringPtr(quoteId)
				inverse = false
			}
			linear = !(inverse == true)
			symbol = SafeStringPtr(*base + "/" + *quote + ":" + *settle)
			if future {
				symbol = SafeStringPtr(*base + "/" + *quote + ":" + *settle + "-" + this.Yymmdd(expiry))
			}
		}
		result = append(result, map[string]any{
			"id":                    id,
			"symbol":                symbol,
			"base":                  base,
			"quote":                 quote,
			"settle":                settle,
			"baseId":                baseId,
			"quoteId":               quoteId,
			"settleId":              settleId,
			"type":                  typeVar,
			"spot":                  false,
			"margin":                false,
			"swap":                  swap,
			"future":                future,
			"option":                false,
			"index":                 index,
			"active":                this.SafeBool(market, "tradeable"),
			"contract":              contract,
			"linear":                linear,
			"inverse":               inverse,
			"contractSize":          this.SafeNumber(market, "contractSize"),
			"taker":                 this.SafeNumber(this.Fees["trading"], "taker"),
			"maker":                 this.SafeNumber(this.Fees["trading"], "maker"),
			"maintenanceMarginRate": nil,
			"expiry":                expiry,
			"expiryDatetime":        this.Iso8601(expiry),
			"strike":                nil,
			"optionType":            nil,
			"precision": map[string]any{
				"amount": amountPrecision,
				"price":  pricePrecision,
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": nil,
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": this.Parse8601(this.SafeString(market, "openingDate")),
			"info":    market,
		})
	}
	var settlementCurrencies []any = SafeListTyped(this.SafeDict(this.Options, "settlementCurrencies", map[string]any{}), "flex")
	var currencies []any = []any{}
	for i := 0; i < len(settlementCurrencies); i++ {
		var code *string = this.SafeString(settlementCurrencies, i, "")
		currencies = append(currencies, map[string]any{
			"id":        strings.ToLower(*code),
			"numericId": nil,
			"code":      code,
			"precision": nil,
		})
	}
	this.PublishCurrencies(this.DeepExtend(currencies, this.Currencies()))

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}

