	//                    },
	//                    {
	//                        "contracts":250000,
	//                        "initialMargin":0.04,
	//                        "maintenanceMargin":0.02
	//                    },
	//                    ...
	//                ],
	//                "isin": "GB00JVMLMP88",
	//                "retailMarginLevels": [
	//                    {
	//                        "contracts": 0,
	//                        "initialMargin": 0.5,
	//                        "maintenanceMargin": 0.25
	//                    }
	//                ],
	//                "tags": [],
	//            },
	//            {
